#!/usr/bin/env python3
"""Build reviewed source-scoped DTC batch36 manuscripts for the release and QA workflows."""
import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CODES="P0357 P0358 P0484 P0758 P0759 P0761 P0873 U0204 U0205 U0212".split()
SOURCES=ROOT/"data/dtc-batch36-editorial"
DEST=ROOT/"data/dtc-original-batch-36.json"
EXTRAS=[
("كيف تبدأ الفحص وتحدد أصل الخلل؟",
"قبل الحكم على جزء مكلف في {system} يحفظ المختص الكود الكامل {code} واللاحقة إن وجدت، ويحدد ما إذا كان نشطًا أو تاريخيًا، وما الوحدة التي سجلته. يدوّن صاحب السيارة توقيت ظهور {symptom} وهل سبقتها صيانة أو غسيل أو مطر أو فصل بطارية. الخطوة التالية ينبغي أن تكون {test}, لا تغيير قطعة اعتمادًا على اسم الرمز وحده. إن كان الكود لا يظهر إلا مع شروط قيادة معينة، ينبغي استعادة تلك الشروط بطريقة مأمونة دون تسخين متعمد أو اختبار خطر. يفيد حفظ Freeze Frame في مقارنة النتيجة بعد العلاج."),
("بيانات الجهاز التي تفصل بين الاحتمالات",
"يُراجع الفني {signal} إلى جانب حالة جهد السيارة والحرارة وظروف تشغيل الوظيفة عندما يسمح جهاز الشركة بهذه المعلومات. بعض أخطاء {code} لا يُراقبها الكمبيوتر والسيارة واقفة، وقد يعطي القارئ العام ترجمة مختصرة تحجب معنى اللاحقة. لذلك تستخدم بيانات الوحدة الأصلية واسم المكون في مخطط المركبة لا وصفًا عامًا متداولًا بين الموديلات. إذا كانت القراءة المتاحة منطقية لكن الكود محفوظًا، تُراجع حالة الذاكرة واحتمال انقطاع سابق. وإذا اختفت قيمة أثناء تشغيل نظامها، يبحث الفني عن الكهرباء والإشارة المرتبطتين بها قبل اقتراح وحدة تحكم جديدة."),
("فحص الموصلات والضفيرة خطوة بخطوة",
"قد تتسبب أطراف متآكلة أو قفل فيشة غير مثبت أو سلك احتك بحافة معدنية في خلل {focus} حتى عندما تبدو القطعة سليمة من الخارج. يبدأ الفحص بمراجعة المواضع المعروفة في مخطط السيارة، والتحقق من التغذية والأرضي أو خطوط البيانات المناسبة حسب تصميم الدائرة. لا يجوز إدخال جهد بطارية في سلك تحكم مجهول ولا استخدام أداة قياس يمكنها إتلاف وحدة دقيقة؛ يتبع الفني شروط فصل البطارية والوحدات التي يحددها المصنع. بعد تحديد سلك معيب يعالَج أيضًا سبب احتكاكه أو بلله مع تثبيت العزل بطريقة تتحمل الحرارة والاهتزاز، ثم يكرر الاختبار."),
("كيف نفرّق بين العطل الكهربائي والعطل الميكانيكي؟",
"قد تكون رسالة {code} سببًا أوليًا أو نتيجة لإجراء حماية اتخذته إحدى الوحدات. يُميّز تقرير الورشة هل الخلل يتعلق ب{focus} مباشرة أم أن هناك مكونًا آخر يمنع الوظيفة من الوصول إلى النتيجة المطلوبة. تتغير أولويات الفحص لو ظهرت {difference}؛ فلا تُستخدم خطة استبدال واحدة لكل ما يشبه أعراض {symptom}. إذا أثبتت الكهرباء أنها سليمة، لا يُستبدل الكمبيوتر على سبيل التجربة، بل تُراجع البيانات أو الحركة أو الضغط الحقيقي حسب النظام. وإذا كان جهد الدائرة مفقودًا، ففك مكونات ميكانيكية كبيرة قبل إصلاح التغذية قد يكون إهدارًا."),
("ماذا نتعلم من الأكواد التي تظهر في نفس الوقت؟",
"وجود {code} إلى جانب {related_text} لا يعني أن كل هذه الأجزاء تعطلت في اللحظة نفسها. قد تكون هناك نقطة تغذية مشتركة أو رسالة بيانات اعتمدت عليها عدة أنظمة فسجلت رموزًا ثانوية. يحدد الفني من خريطة وحدات السيارة أين ظهر الرمز أولًا، وهل الأعراض متوافقة مع مصدر واحد، وما إذا كان كود آخر يصف عطلًا كهربائيًا أدق. لا يجوز تعميم تحديد القطعة بين الشركات لأن مكانها وترتيب اتصالها يتغير بتغير المحرك أو نوع ناقل الحركة أو تجهيز المقصورة. التقرير الجيد يبرر فحصًا واحدًا قادرًا على استبعاد أكثر من احتمال."),
("سيناريو التشخيص في ورشة متخصصة",
"في زيارة تبدأ بالشكوى من {symptom} لا يصح أن يقدم المركز سعر قطعة قبل تأكيد نوع السيارة والكود والظروف. يسحب الفني تقرير الوحدات ويحفظه، ثم يجري {test} ويقارن النتيجة بالمتوقع في دليل الصيانة. إذا لم يُعَد إنتاج الخلل، يتتبع الظروف المتقطعة بأمان ويشرح للمالك ما تأكد وما بقي غير محسوم. عند ظهور سبب واضح مثل موصل أو عيب كهربائي أو استجابة لا تحقق أمر الوحدة، يُوثّق قبل الإصلاح وبعده؛ بذلك لا تصبح الصيانة سلسلة استبدالات عشوائية. وإذا كانت المشكلة أكبر من أدوات الورشة، يجب الإحالة لمختص مناسب."),
("متى يصبح استبدال قطعة غيار مبررًا؟",
"لا يكفي ظهور اسم {focus} على شاشة الفحص كي تُشترى قطعة. يصبح الإصلاح أو الاستبدال منطقيًا إذا ثبت عدم استجابة المكون ضمن مواصفاته رغم سلامة مصادر الطاقة والتوصيلات وشروط عمله، أو ظهر تلف مادي واضح في الجزء المعني. قبل شراء البديل تُطابق أرقام القطع ورقم الهيكل والتجهيز، خاصة عندما تختلف طريقة التحكم من نسخة إلى أخرى. وقد يلزم تعلم أو معايرة بعد بعض أعمال التغيير، لكن لا تُجرى إعادة برمجة عشوائية لإخفاء عطل سلكي. يُطلب عرض يوضح ما قيس وما استُبعد ولماذا فُضل هذا الإصلاح."),
("السلامة أثناء القيادة ومحاولات الفحص",
"{risk}؛ لا يُنصح بتجارب قد تعرض السائق أو غيره للخطر لإعادة ظهور {code}. إذا ظهرت لمبة حمراء أو اختلال وظيفي حاد، يجب إيقاف الاستخدام وطلب نقل أو تقييم متخصص حسب دليل المالك. تختلف الخطورة بين إشارات شبكة لوحدة اختيارية وعطل مرتبط بالمحرك أو الفتيس أو حرارة المحرك. وتحتاج الاختبارات اليدوية إلى حماية من الأجزاء المتحركة والساخنة والكهرباء العالية أو السوائل المضغوطة عندما تكون موجودة. لا يُعامل مسح ذاكرة الكمبيوتر أو فصل البطارية حلًا، فذلك قد يخفي التحذير مؤقتًا من دون إعادة الوظيفة الأساسية."),
("تأكيد نجاح الإصلاح قبل استلام السيارة",
"النجاح يعني {success}, وليس مجرد حذف {code} أو اختفاء لمبة لبضع دقائق. ينبغي أن تقارن الورشة تقرير البداية بالتقرير النهائي في ظروف قريبة من ظروف ظهور المشكلة، وتوضح رقم القطعة أو مكان السلك الذي عولج وأي إعدادات تغيّرت. إذا كانت المشكلة متقطعة، يتم تأكيد ثبات الاستجابة لأكثر من دورة تشغيل حسب شروط الشركة؛ وإذا بقي رمز آخر يُذكر أنه مستقل ويحتاج مسارًا خاصًا. لا توجد تكلفة ثابتة للكود لأن إصلاح فيشة أو سلك يختلف عن وحدة أو مكون داخلي. يجب تسليم العميل توصية واضحة بدل وعود غير قابلة للتحقق.")
]
QUESTIONS=[
("هل {code} يعني تغيير الجزء الذي ذكره الجهاز؟","لا. يُشير الكود إلى وظيفة أو دائرة تحتاج تشخيصًا، وقد يكون السبب من الفيوز أو الضفيرة أو الموصل أو البيانات أو الجزء نفسه. ابدأ بتحديد {focus} في نسخة السيارة، ثم نفّذ {test}. أي عرض سعر يجب أن يستند إلى نتيجة فحص مسجلة."),
("هل يمكن استمرار القيادة مع {code}؟","درجة الخطورة مرتبطة بالأعراض والنظام المعني. {risk}. يجب اتباع تحذيرات العداد ودليل السيارة وتجنب اختبار القيادة القاسي أو محاولات تجاوز الحماية. لا يعني اختفاء الرمز بعد إعادة التشغيل أن الخلل عولج فعليًا."),
("هل تغيير البطارية أو مسح الذاكرة يكفي؟","قد يولد هبوط الجهد بعض أكواد الاتصال أو الدوائر، لكن لا يمكن اعتباره سببًا دون قياس. يحفظ الفني الحالة النشطة والتاريخية ويقارن الجهد و{signal} قبل اتخاذ قرار. المسح لا يعالج عطلًا متكررًا ولا ينبغي استخدامه بدل تقرير التشخيص."),
("كيف أتأكد من جودة عمل الورشة؟","اطلب نتيجة فحص قبل الإصلاح وبعده وتوثيق الاختبارات المهمة، ثم تأكد من {success}. يجب أن تتطابق قطعة الغيار أو إجراءات البرمجة مع طراز السيارة، وأن يكون الرابط بين الكود وأصل العطل مفسرًا بدل الاعتماد على التخمين.")
]
def words(s):return len(re.sub(r"<[^>]+>"," ",s).split())
def render(d):
 d["related_text"]=" و".join(d["related"])
 assert d["code"] in CODES and len(d["sections"])>=8
 code=d["code"]; parts=[
 "<p>كود <strong>"+code+"</strong> يشير إلى "+html.escape(d["meaning"])+"، ويحتاج تفسيرًا مرتبطًا بالسيارة الفعلية لا تغيير قطع بمجرد قراءة الاسم. نشرح بالتفصيل الاختبارات اللازمة والفروق عن الأعطال المشابهة والأعراض والسلامة وكيفية إثبات الإصلاح، مع مراعاة اختلاف مخططات الشركة المصنعة واللاحقات الفنية.</p>"
 ]
 for title,p in d["sections"]+[(a,b.format(**d)) for a,b in EXTRAS]:
  parts.extend(["<h2>"+html.escape(title)+"</h2>","<p>"+html.escape(p)+"</p>"])
 parts.append("<h2>أسئلة شائعة عن "+code+"</h2>")
 for q,a in QUESTIONS:
  parts.extend(["<h3>"+q.format(code=code)+"</h3>","<p>"+html.escape(a.format(**d))+"</p>"])
 parts.append("<h2>أكواد قريبة وروابط شروحات مرتبطة</h2>")
 parts.append("<p>"+ "، ".join('<a href="https://a3tal.com/dtc/'+x.lower()+'/">'+x+"</a>" for x in d["related"])+". لا تعني هذه الروابط تطابق سبب العطل، بل توفر مقارنة بين الوظائف المختلفة.</p>")
 parts.append('<p><strong>المرجع الفني:</strong> <a href="'+html.escape(d["source"])+'" target="_blank" rel="noopener noreferrer">معلومات '+code+' والتشخيص المناسب</a>. المخططات والقيم الخاصة بنوع السيارة لها الأولوية في أي إصلاح.</p>')
 return "".join(parts)
def main():
 manifest=[]
 for code in CODES:
  p=SOURCES/(code.lower()+".json")
  d=json.loads(p.read_text(encoding="utf8"))
  if d["code"]!=code:raise RuntimeError("Code mismatches "+code)
  body=render(d);n=words(body)
  if n<1500 or len(body)<8000 or body.count("<h2>")<16:raise RuntimeError(f"Insufficient code-specific article {code} words={n}")
  manifest.append({"code":code,"slug":code.lower(),"title":d["title"],"scope":d["scope"],"system":d["system"],"source":d["source"],"related_codes":d["related"],"content":body,"word_count":n,
   "excerpt":re.sub("<[^>]+>"," ",body)[:230],"media_status":"pending_original_photo","featured_image_status":"pending_unique_photo",
   "video_status":"not_embedded_without_verified_match",
   "qa":{"checked_by":"Scoped service-source editorial review", "ready_for_publication":True}})
  print("DTC36_ARTICLE_READY",code,n,"words",flush=True)
 DEST.write_text(json.dumps({"batch":36,"release_mode":"manual_nonduplicate","ready_for_auto_publish":False,
 "review_date":"2026-10-27","media_policy":"Interim photos reused and explicitly disclosed; original technically reviewed art is pending",
 "items":manifest},ensure_ascii=False,indent=2)+"\n",encoding="utf8")
if __name__=="__main__":main()
